// SEO/GEO content hub — long-form guides about Val Thorens.
// Pure data, no styling — consumed by /guide (listing) and /guide/[slug] (article).
//
// Markup in the texts (intro, paragraphs, list items, table cells, FAQ answers):
//   [text](/path) is a link (to our pages, or to another site with a full URL)
//   **text** is bold
// The FAQ structured data gets the plain text (plainText below).

import { SITE } from "./site";

export type GuideFaq = { q: string; a: string };
/** a table: the first cell of every row is that row's header */
export type GuideTable = { caption?: string; head: string[]; rows: string[][] };
export type GuideSection = {
  heading: string;
  paragraphs?: string[];
  list?: string[];
  /** a numbered list (steps, a checklist) instead of bullets */
  ordered?: boolean;
  /** shown after the paragraphs and the list */
  table?: GuideTable;
  /** paragraphs after the list or the table */
  after?: string[];
  /** a live table instead: the cheapest open apartment of every Saturday, from
      the database (notes by the Saturday's ISO date). `only` keeps just those
      Saturdays (a week with nothing open still gets its row), and `count`
      adds how many apartments are still open */
  liveWeeks?: { notes: Record<string, string>; only?: string[]; count?: boolean };
};
export type GuideSource = { title: string; url: string };
export type Guide = {
  slug: string;
  title: string; // the H1
  metaTitle: string;
  description: string;
  keywords: string[];
  emoji: string;
  published?: string; // ISO date, only when known
  updated: string; // ISO date
  intro: string;
  sections: GuideSection[];
  faqs: GuideFaq[];
  /** listed under "מקורות" at the end, and the Article's citation */
  sources?: GuideSource[];
};

/** a guide text without its markup: a link keeps its text, bold loses its stars */
export const plainText = (s: string) =>
  s.replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, "$1").replace(/\*\*(.+?)\*\*/g, "$1");

