  "מתי-לנסוע-לואל-טורנס": ["מזג-אוויר-ושלג-בואל-טורנס", "חופשת-סקי-בחנוכה", "חופשת-סקי-בפסח"],
  "מזג-אוויר-ושלג-בואל-טורנס": ["מה-לארוז-לחופשת-סקי", "מתי-לנסוע-לואל-טורנס", "חופשת-סקי-בחנוכה"],
