/** a guide's related guides; a guide that isn't listed above gets the ones after it */
export function relatedGuides(slug: string, n = 3): Guide[] {
  const picked = (RELATED[slug] ?? [])
    .map(s => GUIDES.find(g => g.slug === s))
    .filter((g): g is Guide => !!g && g.slug !== slug);
  const at = GUIDES.findIndex(g => g.slug === slug);
  for (let k = 1; picked.length < n && k < GUIDES.length; k++) {
    const g = GUIDES[(at + k) % GUIDES.length];
    if (g.slug !== slug && !picked.includes(g)) picked.push(g);
  }
  return picked.slice(0, n);
}
